      cpu: "number",
      disk: "string",
      env: "repeated",
      image: "string",
      integration: "repeated",
      memory: "string",
      name: "string",
      "no-email": "bool",
      "no-pool": "bool",
      pool: "string",
      prompt: "string",
      "registry-auth": "string",
      sandbox: "bool",
      "setup-script": "string",
      standalone: "bool",
      tag: "repeated",
